pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata _tos, uint256[] calldata v) public {
        // 1. Admissible domain: caller must be the required sender, arrays non-empty and same length,
        //    and no overflow/underflow in the internal mul.
        address SENDER = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        // Restrict v[i] to avoid overflow in mul_uint256 by bounding its maximum value.
        // mul_uint256 multiplies by 1e18; max safe value is type(uint256).max / 1e18.
        for (uint256 i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1e18);
        }

        // 2. Execute the call as the required sender.
        vm.prank(SENDER);
        (bool success, bytes memory retData) = address(c).call(abi.encodeWithSelector(C.transfer.selector, _tos, v));
        // If the call reverted, skip this fuzz input to enforce the property only on successful executions.
        vm.assume(success);

        // 3. Assert: the returned value must be true for the reference contract.
        // The buggy version returns false, so the assertion fails for it on any successful input.
        assertTrue(abi.decode(retData, (bool)));
    }
}

