pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 vLen) public {
        // bind length to 0..50 to keep the domain wide but avoid huge arrays
        bound(vLen, 0, 50);
        address[] memory tos = new address[](vLen);
        uint256[] memory values = new uint256[](vLen);
        for (uint256 i = 0; i < vLen; i++) {
            tos[i] = address(0);
            values[i] = 0;
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok = false;
        try c.transfer(tos, values) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        // For empty array (vLen == 0), reference reverts so ok must be false; mutant succeeds, so ok becomes true.
        assertTrue(!(vLen == 0 && ok));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // 1. Admissible domain: caller must be the required sender, and arrays must have matching lengths to avoid
        //    an out-of-bounds revert that is not the bug we target.
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.assume(_tos.length == v.length);
        vm.prank(requiredSender);

        // 2. We need to observe whether the call reverts.  The bug difference is that the reference reverts for
        //    empty _tos, the mutant succeeds.  A low-level call to an EOA always succeeds, but the difference is
        //    in the transfer function's own behavior (revert vs return true), not in the external call's return.
        //    We therefore wrap the call in a try/catch to detect revert.
        bool succeeded;
        try c.transfer(_tos, v) returns (bool result) {
            succeeded = result;
        } catch {
            succeeded = false;
        }

        // 3. General rule: if the call succeeded (did not revert), then _tos.length must be > 0.
        //    Reference satisfies this for all admissible inputs;
        //    mutant violates it when _tos.length == 0 and the call succeeds.
        assertTrue(!succeeded || _tos.length > 0);
    }
}
